cat > /tmp/engine.py << 'EOF'
import numpy as np,pickle
SEG=['S1','S2','S3','S4','S5','S6']
PD={'S1':0.02,'S2':0.05,'S3':0.12,'S4':0.30,'S5':0.60,'S6':0.90}
EV=np.array([(1-PD[s])*1000-PD[s]*16000 for s in SEG])
models=pickle.load(open('/tmp/models.pkl','rb'))
BPS={c:models[c]['BP'] for c in ['income','bureau','bank']}

def solve(post,maxleft):
    memo={}
    def rec(post,left):
        key=(tuple(np.round(post,4)),left)
        if key in memo: return memo[key][0]
        best=max(0.0,float(post@EV)); bestact=('stop',None)
        if left>0:
            for check,BP in BPS.items():
                pb=post@BP; ev=-20.0
                for b in range(6):
                    if pb[b]<1e-5: continue
                    npb=post*BP[:,b]; s=npb.sum()
                    if s<=0: continue
                    npb=npb/s
                    ev+=pb[b]*rec(npb,left-1)
                if ev>best+1e-9: best=ev; bestact=('check',check)
        memo[key]=(best,bestact); return best
    val=rec(post,maxleft)
    act=memo[(tuple(np.round(post,4)),maxleft)][1]
    return val,act

def decide(post):
    return 'approve' if float(post@EV)>0 else 'decline'

def upd(post,check,band):
    BP=BPS[check]
    npb=post*BP[:,band]; return npb/npb.sum()
EOF
